import {fields,planFields,actualFields,mappingFor,rowsFrom,validatePlan,audit,categories,empty,demo} from './model.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isDemo=new URLSearchParams(location.search).get('demo')==='1';
let s=empty(),revision=0,tab='import',modal=null,uploadKind='plan',busy=false,result=null;
const localDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let checkDate=isDemo?'2026-11-05':localDate();
const btn=(text,act,extra='',kind='secondary')=>`<button class="${kind}" data-action="${act}" ${extra}>${text}</button>`;
const version=()=>s.versions.find(v=>v.id===s.activeVersion);
const safeURL=x=>{try{const u=new URL(x);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}};
const link=x=>safeURL(x)?`<a class="inline-link" href="${esc(safeURL(x))}" target="_blank" rel="noopener noreferrer">${esc(x)}</a>`:esc(x||'未提供');
const toast=x=>{$('#toast').textContent=x;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500)};
async function api(path,body){const r=await fetch('/api/media-plan/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Local-Review':'1'}:{},body:body?JSON.stringify(body):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'操作失败');return v;}
async function save(){if(isDemo){localStorage.setItem('media-plan-demo-v1',JSON.stringify(s));return;}const v=await api('state',{revision,state:s});revision=v.revision;}
async function commit(next,message){const previous=s;s=next;try{await save();render();if(message)toast(message)}catch(e){s=previous;render();toast('未保存：'+e.message);throw e;}}
function render(){const v=version();$('#app').innerHTML=`<div class="headerbar"><b>demo · 广告检查工作台</b><a href="../">首次接入</a><a href="../daily/">日常报告</a><span class="mode-pill">${isDemo?'虚构案例演示':'真实文件测试区 · 本地保存'}</span></div><main class="mp-main"><div class="mp-header"><div><div class="eyebrow">MEDIA PLAN REVIEW</div><h1>按品牌计划核对，不重复审文案</h1><p>demo / demo-DE · 不修改广告 · 不自动发送飞书</p></div><div class="actions"><a href="${isDemo?'./':'?demo=1'}">${isDemo?'进入真实文件测试区':'先体验虚构案例'} →</a>${btn('导出测试记录','export')}</div></div><div class="source-banner"><strong>${isDemo?'以下素材、文案、广告与优惠差异全部为虚构案例':'品牌 Media Plan 是执行依据，明确的行直接录入'}</strong><p>${isDemo?'用于体验导入、问题分类和反馈，不代表账户真实问题。与真实测试文件分开保存。':'只请你处理读不到、归属不明或版本冲突的部分；不会要求你重新审核外语搭配。当前模块尚未接通实时广告、OCR 或网页抓取。'}</p></div><nav class="mp-tabs">${[['import','1 导入资料'],['standard','2 品牌执行标准'],['results','3 执行核对'],['history','4 版本与反馈']].map(([k,l])=>btn(l,'tab',`data-tab="${k}"`,tab===k?'active':'')).join('')}</nav>${tab==='import'?importView():tab==='standard'?standardView(v):tab==='results'?resultsView(v):historyView()}</main>`;}
function importView(){return `<div class="mp-grid"><section class="panel"><h2>把品牌方原文件放进来</h2><p class="source-location">Excel 保留工作表与行号；图片和 ZIP 整理为素材目录。不要求品牌改模板。</p><div class="upload-area"><b>上传 Media Plan 和素材附件</b><input id="files" type="file" multiple accept=".xlsx,.csv,.tsv,.txt,.json,.zip,.png,.jpg,.jpeg,.webp,.gif,.pdf,.docx"><p>${isDemo?'演示区不接收真实文件，请切换到真实文件测试区。':'支持 XLSX / CSV / TSV / JSON；可同时放入图片或 ZIP 包。单文件最多 12 MB。'}</p></div><div class="actions">${btn('粘贴表格内容','paste','','text')}${btn('登记下载链接','link','','text')}</div><div class="doc-list">${s.documents.map((d,i)=>`<div class="doc-row"><div><b>${esc(d.name)}</b><small>${d.sheets.length} 个工作表 · ${d.assets.length} 张图片 · ${d.gaps.length} 项读取说明</small></div>${d.sheets.length?btn('对应列并录入','map',`data-index="${i}"`):btn('查看读取范围','doc',`data-index="${i}"`,'text')}</div>`).join('')||'<div class="empty">还没有导入文件。也可以先体验右上角的虚构案例。</div>'}</div>${s.sources.map(x=>`<div class="row-gap">下载来源：${link(x.url)}<br>已登记，未下载。请上传文件后关联；不能当作素材读取成功。</div>`).join('')}</section><section class="panel capabilities"><h2>本版能读到哪里</h2><b>已实现</b><p>Excel 单元格、可提取的超链接和嵌入图片；CSV/表格粘贴；图片与 ZIP 图片目录；列映射；来源行追溯；版本保存；导入实际广告后的原文差异核对。</p><b>需要你补充的只有缺口</b><p>下载目录包含多种产品、合并单元格归属不明、图片没取到、缺少产品/市场/语言。这些不等于搭配错误。</p><b>尚未接通</b><p>网盘登录与自动下载、PDF/截图 OCR、图片内容识别、完整视频、实时 Meta 拉取、活动页产品定位与抓取。页面优惠只能对照你导入的已核实证据。</p><div class="notice">本地文件按原始摘要留档；真实测试记录保存在本机。此模块的测试版本不覆盖首次接入标准。</div></section></div>`;}
function planCard(r){return `<article class="plan-card"><div class="section-head"><h3>${esc(r.product)} · ${esc(r.market)} · ${esc(r.language)}</h3><span class="source-chip">品牌原文直接作为依据</span></div><p class="source-location">${esc(r.source)} · 计划行 ${esc(r.plan_key)}</p><div class="copy-grid"><div>${r.assets?.length?r.assets.map(a=>`<div>${a.preview?`<img class="asset-preview" src="${esc(a.preview)}" alt="${esc(a.name)}">`:'<div class="asset-placeholder">已记录原文件，预览过大或格式不支持</div>'}<small>${esc(a.name)}</small></div>`).join(''):`<div class="asset-placeholder">${r.asset?'来源已登记，原图未读取':'未提供素材'}</div>`}</div><div>${['body','headline','description'].map(k=>`<div class="copy-field"><small>${fields[k]}</small>${k in r?esc(r[k]||'品牌明确留空'):'该列没有录入，暂不核对'}</div>`).join('')}</div></div><div class="rule-line">优惠：${esc(r.offer||'未声明')} ${esc(r.currency||'')} · ${esc(r.condition||'条件未声明')}<br>适用：${esc(r.campaign?'Campaign 包含 '+r.campaign:'本产品 / 市场 / 语言')} · ${esc(r.start||'未限开始')} 至 ${esc(r.end||'未限结束')}</div><p>素材来源：${link(r.asset)}</p><p>页面：${link(r.url)}</p>${!r.assets?.length?'<div class="row-gap">原素材检查不到；文案等已读取字段仍可独立核对。不会要求你判断外语是否合理。</div>':''}</article>`;}
function standardView(v){return `<section class="panel"><h2>${v?esc(v.label):'还没有品牌执行标准'}</h2><p class="source-location">${v?`测试版本 ${esc(v.id)} · ${v.rows.length} 行。无需逐组“搭配正确”确认。`:'先导入品牌计划，检查列对应关系后直接录入。'}</p>${v?'<div class="notice">结构明确即作为品牌执行依据。素材未读取或来源不明保持缺口；当前投放值不会反向覆盖计划。</div>':btn('去导入资料','tab','data-tab="import"','primary')}</section>${v?v.rows.map(planCard).join(''):''}`;}
function resultsView(v){result=v?audit(v,s.actual,checkDate):null;const gs=result?.groups||[],issues=gs.filter(g=>g.category!=='UNCHECKABLE'),gaps=gs.filter(g=>g.category==='UNCHECKABLE');return `<section class="panel"><div class="mp-header"><div><h2>把实际执行与品牌计划放在一起看</h2><p>${isDemo?'示例已预置，可直接展开问题并反馈。':'本次需导入实际广告文件；不会在打开页面时自动读取 Meta。'}</p></div><div class="actions">${btn('导入实际广告','actual','','primary')}${btn('粘贴实际配置','paste','data-kind="actual"')}</div></div><div class="form-grid"><label class="field">检查日期<input id="check-date" type="date" value="${esc(checkDate)}"></label><label class="field">对照品牌版本<select id="version">${s.versions.map(x=>`<option value="${esc(x.id)}" ${x.id===s.activeVersion?'selected':''}>${esc(x.label)} · ${esc(x.id)}</option>`).join('')}</select></label></div>${v?`<div class="mini-stats"><div><b class="big-stat">${s.actual.length}</b><small>已导入广告</small></div><div><b class="big-stat">${issues.length}</b><small>去重后的差异 / 缺少依据</small></div><div><b class="big-stat">${gaps.length}</b><small>检查不到的分组</small></div><div><b class="big-stat">${result.excluded}</b><small>关闭广告已排除</small></div></div>`:'<div class="notice">请先录入品牌计划。</div>'}<p class="small">同一问题合并展示，展开查看全部广告。反馈不关闭问题，也不会把实际值变成品牌标准。</p></section>${!s.actual.length?'<div class="panel empty">尚未导入实际广告，不能判断执行是否符合计划。</div>':issues.map((g,i)=>resultCard(g,i)).join('')||'<div class="panel notice">本次可比字段未发现差异。下方检查不到的部分仍未完成，不代表全部通过。</div>'}${gaps.length?`<details class="panel"><summary>这些检查不到 · ${gaps.length} 组</summary>${gaps.map((g,i)=>resultCard(g,i+issues.length,false)).join('')}</details>`:''}<section class="panel"><h3>实际广告文件怎么准备</h3><p class="source-location">可以导入 CSV / Excel，然后选择对应列。至少需要广告名称、产品、市场、语言及三级开启状态。计划行编号用于精确对应；未填时仅接受唯一匹配。图片对照需要原文件 SHA256 或后续接入的可靠资产映射。</p>${btn('下载实际广告列模板','template','','text')}<p class="small">图片/页面优惠字段仅接收已核实证据，需带单位、条件、出处和时间；本版不会自动识别图片或读取页面。</p></section>`;}
function resultCard(g,i,feedback=true){const f=s.feedback[g.key];return `<article class="result-card ${feedback?'error-card':'gap-card'}"><span class="tag">${esc(categories[g.category])}</span><h3>${esc(fields[g.field]||g.field)}${g.category==='EXECUTION_DIFFERENCE'?'没有按品牌计划执行':g.category==='PAGE_OFFER_DIFFERENCE'?'与品牌计划不同':g.category==='CONTENT_CONFLICT'?'与优惠标准冲突':''} · 影响 ${g.ads.length} 条广告</h3><p class="source-location">${esc(g.source||'未找到适用的计划行')}</p><div class="result-compare"><div><small>品牌依据</small>${esc(g.expected)}</div><div><small>实际执行 / 已导入证据</small>${esc(g.observed)}</div></div><p class="small">${esc(g.reason)}</p>${g.evidence?`<p class="source-location">证据：${esc(g.evidence)} · ${esc(g.captured_at)}</p>`:''}<details><summary>查看对应广告名称</summary>${g.ads.map(a=>`<div class="doc-row"><div><b>${esc(a.name)}</b><small>Ad Set：${esc(a.adset)}<br>Campaign：${esc(a.campaign)}</small></div></div>`).join('')}</details>${feedback?`<div class="actions">${btn(f?'查看 / 修改反馈':'处理这项','feedback',`data-key="${esc(g.key)}"`,'primary')}<span class="review-status">${f?esc(f.label)+' · 待复核':'尚未反馈'}</span></div>`:''}</article>`;}
function historyView(){return `<div class="mp-grid"><section class="panel"><h2>品牌计划版本</h2>${s.versions.map(v=>`<div class="doc-row"><div><b>${esc(v.label)}</b><small>${esc(v.id)} · ${v.rows.length} 行 · ${esc(v.created_at)}<br>${esc(v.source)}</small></div></div>`).join('')||'<div class="empty">还没有版本。</div>'}<p class="small">新版不删除旧版；检查时可选择版本，逐行生效日期仍参与判断。</p></section><section class="panel"><h2>处理记录</h2>${s.events.slice().reverse().map(e=>`<div class="doc-row"><div><b>${esc(e.text)}</b><small>${esc(e.at)}</small></div></div>`).join('')||'<div class="empty">导入、反馈会记录在这里。</div>'}</section></div>`;}
function open(title,html){$('#overlay').innerHTML=`<div class="scrim"><section class="dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="dialog-head"><div><span class="eyebrow">${isDemo?'虚构演示':'本地真实文件测试'}</span><h2>${esc(title)}</h2></div>${btn('×','close','aria-label="关闭"','close')}</div>${html}</section></div>`;document.body.classList.add('locked');$('#overlay button').focus();}
function close(){modal=null;$('#overlay').innerHTML='';document.body.classList.remove('locked');}
function mappingField(k,header){return `<label class="field">${fields[k]}<select data-map="${k}"><option value="-1">此列没有 / 不核对</option>${header.map((h,i)=>`<option value="${i}" ${modal.map[k]===i?'selected':''}>${esc(h||'空表头')}（第 ${i+1} 列）</option>`).join('')}</select></label>`;}
function showMapping(){const d=s.documents[modal.index],sh=d.sheets[modal.sheet],header=sh.rows[modal.header]?.cells||[];modal.map??=mappingFor(header,modal.kind);const keys=modal.kind==='plan'?planFields:actualFields;open(modal.kind==='plan'?'对应列，直接录入品牌标准':'对应实际广告字段',`<p class="small">已识别的列放在上面，可选项折叠在下面。只核对列有没有读对，不要求审核外语搭配。未选的列不参与检查；选了但单元格为空，表示原表明确留空。</p><div class="form-grid"><label class="field">工作表<select id="sheet">${d.sheets.map((x,i)=>`<option value="${i}" ${i===modal.sheet?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field">表头所在行<select id="header">${sh.rows.slice(0,30).map((r,i)=>`<option value="${i}" ${i===modal.header?'selected':''}>第 ${r.row} 行：${esc(r.cells.filter(Boolean).slice(0,3).join(' / ').slice(0,65))}</option>`).join('')}</select></label></div><div class="data-preview"><table>${sh.rows.slice(modal.header,modal.header+4).map(r=>`<tr><th>${r.row}</th>${r.cells.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</table></div><div class="mapping-grid">${keys.filter(k=>modal.map[k]>=0||["product","market","language",...(modal.kind==="actual"?["ad_name","campaign_status","adset_status","ad_status"]:[])].includes(k)).map(k=>mappingField(k,header)).join('')}</div><details><summary>补充可选列（未选的列不检查）</summary><div class="mapping-grid">${keys.filter(k=>modal.map[k]<0&&!["product","market","language",...(modal.kind==="actual"?["ad_name","campaign_status","adset_status","ad_status"]:[])].includes(k)).map(k=>mappingField(k,header)).join('')}</div></details><div></div>${modal.kind==='plan'?'<label class="field">版本名称<input id="version-label" placeholder="例如：品牌德国黑五计划 11-05 版"></label>':''}<div class="notice">图片只按同表行锚点或唯一文件名关联；一个下载包不会自动配给所有文案。未读取的下载链接保留为缺口。</div>${d.gaps.map(g=>`<div class="row-gap">${esc(g)}</div>`).join('')}<div id="map-error" class="error"></div><div class="dialog-actions">${btn(modal.kind==='plan'?'录入这版品牌计划':'导入并核对','commit-map','','primary')}</div>`);}
function log(next,text){next.events.push({at:new Date().toISOString(),text});}
async function importFiles(files,kind){if(isDemo){toast('真实文件请在真实文件测试区导入，避免与虚构案例混合。');return;}busy=true;toast('正在读取文件与附件…');try{let next=structuredClone(s),first=-1;for(const file of files){if(file.size>12_000_000)throw Error('单个文件最多 12 MB');const bytes=new Uint8Array(await file.arrayBuffer());let b='';for(let i=0;i<bytes.length;i+=8192)b+=String.fromCharCode(...bytes.subarray(i,i+8192));const d=await api('import',{name:file.name,data:btoa(b)});if(first<0&&d.sheets.length)first=next.documents.length;next.documents.push(d);}log(next,`读取 ${files.length} 个文件；原文件保存在本机`);await commit(next,'文件已读取，下一步核对列');if(first>=0){modal={index:first,sheet:0,header:0,kind};showMapping();}}catch(e){toast(e.message)}finally{busy=false;}}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
document.addEventListener('change',async e=>{if(e.target.id==='files')return importFiles([...e.target.files],'plan');if(e.target.id==='actual-files')return importFiles([...e.target.files],'actual');if(e.target.dataset.map)modal.map[e.target.dataset.map]=+e.target.value;if(['sheet','header'].includes(e.target.id)){modal[e.target.id]=+e.target.value;if(e.target.id==='sheet')modal.header=0;modal.map=null;showMapping();}if(e.target.id==='check-date'){checkDate=e.target.value;render();}if(e.target.id==='version'){const next=structuredClone(s);next.activeVersion=e.target.value;try{await commit(next,'已切换对照版本')}catch{}}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||busy)return;const act=b.dataset.action;
if(act==='close')return close();if(act==='tab'){tab=b.dataset.tab;render();return;}if(act==='export')return download('Media-Plan-'+(isDemo?'虚构演示':'真实测试')+'.json',JSON.stringify({saved_at:new Date().toISOString(),state:s,report:version()?audit(version(),s.actual,checkDate):null},null,2));
if(act==='map'){modal={index:+b.dataset.index,sheet:0,header:0,kind:'plan'};showMapping();}
if(act==='doc'){const d=s.documents[+b.dataset.index];open(d.name,`${d.gaps.map(g=>`<div class="notice">${esc(g)}</div>`).join('')}${d.assets.map(a=>`<div class="doc-row">${a.preview?`<img class="asset-preview" src="${esc(a.preview)}" alt="素材预览">`:''}<div><b>${esc(a.name)}</b><small>文件已读取，尚未识别压字</small></div></div>`).join('')}`);}
if(act==='paste'){uploadKind=b.dataset.kind||'plan';if(isDemo)return toast('请进入真实文件测试区');open('粘贴从表格复制的内容','<p class="small">带上表头，保留制表符；无需先翻译。</p><label class="field">来源名称<input id="paste-name" value="粘贴的品牌计划"></label><label class="field">表格内容<textarea id="paste-table" rows="10"></textarea></label><div class="dialog-actions">'+btn('读取表格','read-paste','','primary')+'</div>');}
if(act==='read-paste'){const file=new File([$('#paste-table').value],($('#paste-name').value||'品牌计划')+'.tsv');await importFiles([file],uploadKind);}
if(act==='link'){if(isDemo)return toast('请进入真实文件测试区');open('登记品牌素材下载链接','<p class="notice">本版记录来源，不自动登录或下载；链接登记后仍为读取缺口。</p><label class="field">完整链接<input id="source-url"></label><div class="dialog-actions">'+btn('登记来源','save-link','','primary')+'</div>');}
if(act==='save-link'){const u=$('#source-url').value;if(!safeURL(u))return toast('请输入完整 http 或 https 链接');const n=structuredClone(s);n.sources.push({url:u,status:'NOT_DOWNLOADED',at:new Date().toISOString()});try{await commit(n,'已登记来源，尚未下载');close()}catch{}}
if(act==='commit-map'){try{const d=s.documents[modal.index],sh=d.sheets[modal.sheet];const all=s.documents.flatMap(x=>x.assets);const unique=all.filter(a=>all.filter(x=>x.name===a.name).length===1);const rows=rowsFrom(sh,modal.map,modal.header,d,unique,modal.kind);const n=structuredClone(s);if(modal.kind==='plan'){const errs=validatePlan(rows);if(errs.length)throw Error(errs.join('；'));const label=$('#version-label').value.trim();if(!label)throw Error('请给这版计划填写版本名称');const id='v'+(n.versions.length+1);n.versions.push({id,label,created_at:new Date().toISOString(),rows,source:d.name,source_hash:d.sha256});n.activeVersion=id;log(n,`录入品牌计划 ${id}：${rows.length} 行；未要求人工语义审批`);tab='standard';}else{if(!rows.length||rows.some(x=>!x.ad_name))throw Error('请对应广告名称列');n.actual=rows;log(n,`导入实际广告 ${rows.length} 条`);tab='results';}await commit(n,'已保存到本地测试版本');close();}catch(e){$('#map-error').textContent=e.message;}}
if(act==='actual'){if(isDemo)return toast('演示区使用预置数据；真实文件请切换测试区');open('导入实际广告配置','<p class="notice">仅读取文件，不连接广告后台。导入后检查开启状态及原文差异。</p><input id="actual-files" type="file" accept=".xlsx,.csv,.tsv,.json">');}
if(act==='template'){download('实际广告字段模板.csv','\ufeff'+actualFields.join(',')+'\n','text/csv');}
if(act==='feedback'){modal={key:b.dataset.key};const f=s.feedback[modal.key];open('记录处理方式，保留原始依据',`<p class="notice">不会把实际广告自动纳入品牌标准；安排修正后仍需重新取证核对。</p><label class="field">处理方式<select id="feedback-status">${['已安排按计划修正','需要品牌确认','识别有误，申请复核','等待品牌新版计划'].map(x=>`<option ${x===f?.label?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">补充说明<textarea id="feedback-note">${esc(f?.note||'')}</textarea></label><div class="dialog-actions">${btn('保存反馈','save-feedback','','primary')}</div>`);}
if(act==='save-feedback'){const note=$('#feedback-note').value.trim(),label=$('#feedback-status').value;if(label==='识别有误，申请复核'&&!note)return toast('请说明识别错在哪里');const n=structuredClone(s);n.feedback[modal.key]={label,note,at:new Date().toISOString()};log(n,`${label}${note?'：'+note:''}`);try{await commit(n,'反馈已保存；原问题仍保留，等待复核');close()}catch{}}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});
try{if(isDemo){s=JSON.parse(localStorage.getItem('media-plan-demo-v1'))||demo();s.demo=true;tab='results';}else{const saved=await api('state');revision=saved.revision;s=saved.state||empty();}render();}catch(e){render();toast('无法载入保存记录：'+e.message);}
